        "34afe469a2014403b5f1d96eb6049027": {
          "id": "34afe469a2014403b5f1d96eb6049027",
          "name": "Get Catalog item details",
          "script": "(function execute() {\n    \n    var catItemObj = new sn_sc.CatItem(vaVars.catalog_item_id);\n    var catItemJson = catItemObj.getItemSummary(false, 'basic');\n    vaVars.image = catItemJson.picture;\n    vaVars.item_title = catItemJson.name;\n\n    var itemJSON = new sn_sc.CatalogConversationHelper().getItem(vaVars.catalog_item_id);\n    vaVars.itemJSON = JSON.stringify(itemJSON);\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    /* Return true or false to indicate if the topic or topic node can run\n       and be discoverable (or not).  For example:\n\n       var applicability = vaInputs.first_name == 'Bill' ? true : false;\n       return applicability;\n    */\n    return vaVars.catalog_item_id != '' || vaInputs.catalog_item_id != '';\n})()\n"
          }
        },
        "d5964dab81d24218991771a2011e9aa0": {
          "id": "d5964dab81d24218991771a2011e9aa0",
          "stepType": "TextOutput",
          "name": "Description",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    var itemJson = JSON.parse(vaVars.itemJSON);\n    if (!gs.nil(itemJson.description))\n        return gs.getMessage(\"Here are some more details about {0}{1}\", [vaVars.item_title, itemJson.description]);\n})()\n",
              "mode": "script"
            }
          ],
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    return vaInputs.catalog_item_id  != '-1';\n})()\n"
          },
          "requestFeedback": true
        },
        "17d46895b0784672a16a5f9c708f0b90": {
          "id": "17d46895b0784672a16a5f9c708f0b90",
          "stepType": "TextOutput",
          "name": "Not found",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    if (vaVars.query_search)\n        return gs.getMessage(\"I'm sorry, I wasn't able to find anything that matches this request, but your questions are helping me learn.\");\n    else\n        return gs.getMessage(\"I'm sorry, I wasn't able to find anything that matches this request.\");\n})()\n",
              "mode": "script"
            }
          ],
          "applicability": {
            "mode": "query",
            "value": ""
          },
          "requestFeedback": true
        },
        "0b2f29d8ced94cc4b9895f3ff2c38e70": {
          "id": "0b2f29d8ced94cc4b9895f3ff2c38e70",
          "stepType": "ImageOutput",
          "name": "Image",
          "url": {
            "value": "(function execute() {\n    /* Return a quoted string.  For example:\n\n       if (vaInputs.first_name == 'Bill') {\n           return gs.getMessageLang(\"hi there {0}\", vaContext.getRequesterLang(), [vaInputs.first_name]);\n       } else {\n           return gs.getMessageLang(\"how are you {0}\", vaContext.getRequesterLang(), [vaInputs.last_name]);\n       }\n    */\n    return vaVars.baseUri + vaVars.image;\n})()\n",
            "mode": "script"
          },
          "altText": {
            "value": "",
            "mode": "simple"
          },
          "variableId": "",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n\n    return vaVars.catalog_item_id != '' && vaInputs.search == '' && vaVars.image_not_shown;\n    \n})()\n"
          }
        },
        "c9b8bfd9637d46c4b14cd1a202bc7851": {
          "id": "c9b8bfd9637d46c4b14cd1a202bc7851",
          "name": "Set catalog item variables",
          "script": "(function execute() {\n    if(vaInputs.catalog_item_id == null && vaVars.catalog_item_id != null)\n      vaInputs.catalog_item_id = vaVars.catalog_item_id;\n    else if(vaVars.catalog_item_id == null && vaInputs.catalog_item_id != null)\n     vaVars.catalog_item_id = vaInputs.catalog_item_id;\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "8a3f6479a5ef42daa8e1721ae744c789": {
